begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(28);
select ok(has_schema_privilege('anon','private','usage') and not has_table_privilege('anon','private.profiles','select') and has_function_privilege('anon','private.can_read_profile_photo(uuid,uuid)','execute'),'anonymous has only the photo permission entry point, no direct profile access');
select ok(not has_table_privilege('authenticated','private.profiles','select'),'no direct profile reads');
select ok(not has_function_privilege('anon','public.owner_workspace()','execute'),'anonymous cannot list owners');
select ok(not has_function_privilege('authenticated','public.public_profile(text)','execute'),'public read is server-only');
select ok(not has_function_privilege('authenticated','private.require_account()','execute'),'account helper is internal');
insert into auth.users(id,email,email_confirmed_at) values
('11111111-1111-4111-8111-111111111111','sql-owner-a@example.test',now()),
('22222222-2222-4222-8222-222222222222','sql-owner-b@example.test',now());
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select is((public.owner_workspace()->>'publishedLimit')::integer,2,'default free publish limit');
select set_config('test.profile',public.mutate_profile('create','10000000-0000-4000-8000-000000000001',body=>' {"label":"private label","name":"SQL owner","handle":"sql-owner-a"}')::text,true);
select is(public.mutate_profile('create','10000000-0000-4000-8000-000000000001',body=>' {"label":"private label","name":"SQL owner","handle":"sql-owner-a"}'),current_setting('test.profile')::jsonb,'create retry is identical');
select throws_ok($$select public.mutate_profile('create','10000000-0000-4000-8000-000000000001',body=>' {"label":"changed","name":"SQL owner","handle":"sql-owner-a"}')$$,'P0001','idempotency_conflict','changed-payload retry conflicts');
select ok(not ((public.owner_workspace()->'profiles'->0) ? 'document'),'workspace returns summaries only');
select set_config('test.document','{"schemaVersion":1,"name":"Published SQL name","bio":"Live bio","appearance":{"theme":"warm","layout":"editorial","shape":"soft"},"blocks":[{"id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","type":"link","visible":true,"label":"Visit","url":"https://example.com"},{"id":"bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb","type":"text","visible":false,"text":"hidden secret"}]}',true);
select throws_ok(format('select public.mutate_profile(''save'',gen_random_uuid(),%L,0,%L::jsonb)',current_setting('test.profile')::jsonb->>'id',jsonb_build_object('label','private label','handle','sql-owner-a','document',jsonb_set(current_setting('test.document')::jsonb,'{appearance,theme}','null'))),'P0001','invalid_document','null theme rejected by direct RPC');
select throws_ok(format('select public.mutate_profile(''save'',gen_random_uuid(),%L,0,%L::jsonb)',current_setting('test.profile')::jsonb->>'id',jsonb_build_object('label','private label','handle','sql-owner-a','document',jsonb_set(current_setting('test.document')::jsonb,'{blocks,0,type}','null'))),'P0001','invalid_document','null block type rejected by direct RPC');
select lives_ok(format('select public.mutate_profile(''save'',gen_random_uuid(),%L,0,%L::jsonb)',current_setting('test.profile')::jsonb->>'id',jsonb_build_object('label','private label','handle','sql-owner-a','document',current_setting('test.document')::jsonb)),'valid document saves');
select throws_ok(format('select public.mutate_profile(''publish'',gen_random_uuid(),%L,0)',current_setting('test.profile')::jsonb->>'id'),'P0001','revision_conflict','stale revision cannot publish');
select lives_ok(format('select public.mutate_profile(''publish'',gen_random_uuid(),%L,1)',current_setting('test.profile')::jsonb->>'id'),'current draft publishes');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select is(public.owner_workspace()->'profiles','[]'::jsonb,'second owner sees empty workspace');
select throws_ok(format('select public.read_profile(%L)',current_setting('test.profile')::jsonb->>'id'),'P0001','not_found','second owner cannot read first draft');
select throws_ok(format('select public.mutate_profile(''unpublish'',gen_random_uuid(),%L,1)',current_setting('test.profile')::jsonb->>'id'),'P0001','not_found','second owner cannot unpublish first profile');
reset role;
select ok(private.valid_url('https://example.com:65535/path?q=x#fragment'),'valid upper port');
select ok(private.valid_url('http://127.0.0.1:3000/'),'valid IPv4 URL');
select ok(private.valid_url('https://[2001:db8::1]:443/'),'valid IPv6 URL');
select ok(not private.valid_url('https://example.com:99999/'),'invalid port rejected');
select ok(not private.valid_url('https://%ZZ/'),'malformed host rejected');
select ok(not private.valid_url('https://[a]/'),'malformed IPv6 rejected');
select ok(not private.valid_url('https://user:pass@example.com/'),'credentials rejected');
select ok(not private.valid_url('javascript:alert(1)'),'unsafe scheme rejected');
set local role service_role;
select is(public.public_profile('sql-owner-a')->'document'->>'name','Published SQL name','server reads selected snapshot');
select ok(public.public_profile('sql-owner-a')::text not like '%hidden secret%' and public.public_profile('sql-owner-a')::text not like '%private label%','snapshot excludes hidden blocks and private label');
select is(public.public_profile('not-present'),null::jsonb,'missing public profile is neutral null');
select * from finish();
rollback;
